      "concept": "Stereochemical course of bimolecular nucleophilic substitution ($\\text{S}_\\text{N}2$).",
      "given": "Optically active chiral alkyl halide (e.g., $(R)$-2-bromooctane) reacting with a strong nucleophile ($OH^-$).",
